window.initPractical=function(app){
// More tools: clocks, counters, quick workouts, calculators and wellbeing, each in its own window.
const {$,read,write,esc,toast,byId}=app,P=PracticalCore,X=ExtrasCore;
const today=()=>FeatureCore.localDate(),title=id=>byId.get(id)?.title||id;
const extra=()=>({...X.extraDefaults(),...read('cal_extra',{})}),saveExtra=x=>{write('cal_extra',x);window.dispatchEvent(new Event('extra-updated'))};
const local=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},setLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
const lastDays=(map,n=120)=>Object.fromEntries(Object.entries(map||{}).sort((a,b)=>a[0].localeCompare(b[0])).slice(-n));
const mmss=s=>{s=Math.max(0,Math.round(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),r=s%60;return (h?h+':'+String(m).padStart(2,'0'):String(m).padStart(2,'0'))+':'+String(r).padStart(2,'0')};
let audio=null;
function tone(f=880,d=.15,v=.12){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume?.();const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.frequency.value=f;o.start(t);o.stop(t+d)}catch{}}
function speak(text){try{if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;const u=new SpeechSynthesisUtterance(text);u.lang='pt-PT';speechSynthesis.speak(u)}catch{}}
const vib=p=>{try{navigator.vibrate?.(p)}catch{}};
let lock=null;const awake=on=>{if(on&&!lock&&navigator.wakeLock)navigator.wakeLock.request('screen').then(l=>{lock=l}).catch(()=>{});if(!on){lock?.release().catch(()=>{});lock=null}};
const runner=()=>app.getRunner?.();
function startWorkout(name,items,options={}){items=items.filter(i=>byId.has(i.id));if(!items.length){toast('Não há exercícios disponíveis para este treino.');return}dialog.close();runner()?.start(name,items,null,'',options)}
const options=list=>list.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');
const moves=[['Pushups','reps'],['Incline_Push-Up','reps'],['Bodyweight_Squat','reps'],['Pullups','reps'],['Chin-Up','reps'],['Bench_Dips','reps'],['Pike_Push-Up','reps'],['Crunches','reps'],['Burpee','reps'],['Butt_Lift_Bridge','reps'],['Plank','s'],['Wall_Sit','s'],['Dead_Hang','s']].filter(([id])=>byId.has(id));
const moveSelect=(id,pick='Pushups',only)=>`<select id="${id}">${moves.filter(m=>!only||m[1]===only).map(([v,u])=>`<option value="${v}" data-unit="${u}"${v===pick?' selected':''}>${esc(title(v))}${u==='s'?' (segundos)':''}</option>`).join('')}</select>`;
// The body profile is shared by every calculator and stays on this device.
function body(){const b=local('cal_ui_body',{}),w=(read('cal_personal',{}).measurements||[]).filter(m=>m.weight).sort((a,c)=>a.date.localeCompare(c.date)).at(-1)?.weight;return {sex:'m',activity:1.375,...b,weight:b.weight||w||''}}
const bodyField=(key,label,attrs)=>{const b=body();return key==='sex'?`<label class="tool-field">Sexo<select data-body="sex">${options([['m','Homem'],['f','Mulher']])}</select></label>`:key==='activity'?`<label class="tool-field">Atividade<select data-body="activity">${options([[1.2,'Quase nenhuma'],[1.375,'Treino 1–3 vezes por semana'],[1.55,'Treino 3–5 vezes por semana'],[1.725,'Treino quase todos os dias'],[1.9,'Trabalho físico e treino']])}</select></label>`:`<label class="tool-field">${label}<input data-body="${key}" type="number" inputmode="decimal" ${attrs} value="${esc(b[key]??'')}"></label>`};
function bodyForm(box,keys,calc){const labels={age:['Idade','min="10" max="100"'],height:['Altura (cm)','min="100" max="230"'],weight:['Peso (kg)','min="25" max="300" step="0.1"'],waist:['Cintura (cm)','min="40" max="200" step="0.5"'],neck:['Pescoço (cm)','min="20" max="70" step="0.5"'],hip:['Anca (cm)','min="50" max="200" step="0.5"'],rest:['Pulsação em repouso (opcional)','min="30" max="120"'],minutes:['Minutos de treino hoje','min="0" max="300"']};
 box.innerHTML=`<div class="tool-form">${keys.map(k=>bodyField(k,...(labels[k]||[k,''])) ).join('')}</div><div id="calcOut" class="tool-out" role="status"></div><p class="source-note">É uma estimativa geral, não um conselho médico. Os dados ficam só neste telemóvel.</p>`;
 const b=body();box.querySelectorAll('select[data-body]').forEach(s=>{s.value=String(b[s.dataset.body])});
 const update=()=>{const v={...body()};box.querySelectorAll('[data-body]').forEach(i=>{v[i.dataset.body]=i.tagName==='SELECT'&&i.dataset.body==='sex'?i.value:i.value===''?'':Number(i.value)});const {minutes,...keep}=v;setLocal('cal_ui_body',keep);$('calcOut').innerHTML=calc(v)||'<p class="source-note">Preenche os campos para ver o resultado.</p>'};
 box.addEventListener('input',update);update()}

// The tool window: one dialog, its timers are cleaned when it closes.
const dialog=document.createElement('dialog');dialog.id='toolDialog';dialog.className='extra-dialog tool-dialog';dialog.setAttribute('aria-labelledby','toolTitle');dialog.innerHTML='<div class="dialog-top"><h2 id="toolTitle"></h2><button id="toolFav" class="icon-button" aria-label="Juntar às tuas ferramentas" title="Juntar às tuas ferramentas">☆</button><button class="icon-button close-dialog" aria-label="Fechar">×</button></div><div id="toolBody"></div>';document.body.append(dialog);
let cleanup=[];const later=fn=>cleanup.push(fn),every=(fn,ms)=>{const t=setInterval(fn,ms);later(()=>clearInterval(t));return t},clean=()=>{cleanup.forEach(f=>{try{f()}catch{}});cleanup=[];awake(false);try{speechSynthesis.cancel()}catch{}};
dialog.addEventListener('close',clean);
function open(id){const t=TOOLS[id];if(!t)return;remember(id);if(t.start){t.start();return}clean();$('toolTitle').textContent=t.icon+' '+t.name;const box=document.createElement('div');$('toolBody').replaceChildren(box);t.run(box);if(!dialog.open)dialog.showModal();setLocal('cal_ui_tool_last',id);const fav=document.getElementById('toolFav');if(fav){fav.textContent=local('cal_ui_tools_fav',[]).includes(id)?'★':'☆';fav.onclick=()=>{const list=local('cal_ui_tools_fav',[]),on=!list.includes(id);setLocal('cal_ui_tools_fav',on?[...list,id].slice(-12):list.filter(x=>x!==id));fav.textContent=on?'★':'☆';renderRecent();toast(on?'★ Nas tuas ferramentas.':'Tirada das tuas ferramentas.')}}}
function remember(id){setLocal('cal_ui_tools_recent',[id,...local('cal_ui_tools_recent',[]).filter(x=>x!==id)].slice(0,6));renderRecent()}
function renderRecent(){const box=document.getElementById('toolRecent');if(!box)return;const favs=local('cal_ui_tools_fav',[]).filter(id=>TOOLS[id]),list=local('cal_ui_tools_recent',[]).filter(id=>TOOLS[id]&&!favs.includes(id));box.innerHTML=(favs.length?`<span>★ As tuas ferramentas</span><div>${favs.map(id=>`<button type="button" class="chip" data-tool="${id}">${TOOLS[id].icon} ${esc(TOOLS[id].name)}</button>`).join('')}</div>`:'')+(list.length?`<span>Usadas há pouco</span><div>${list.map(id=>`<button type="button" class="chip" data-tool="${id}">${TOOLS[id].icon} ${esc(TOOLS[id].name)}</button>`).join('')}</div>`:'')}

// Shared engine for breathing exercises.
function breathe(box,phases,{cycles=0,minutes=2}={}){box.innerHTML=`<div class="tool-chips">${[1,2,3,5].map(m=>`<button type="button" data-min="${m}" aria-pressed="${m===minutes}">${m} min</button>`).join('')}</div><div class="breath-ball" aria-hidden="true"><span></span></div><p id="brPhase" class="tool-phase">Pronto?</p><p id="brLeft" class="run-big tool-clock">${mmss(cycles?cycles*phases.reduce((n,p)=>n+p[1],0):minutes*60)}</p><div class="tool-row"><button id="brGo" class="primary">▶ Começar</button><label class="tool-check"><input id="brVoice" type="checkbox" checked> Voz</label></div>`;
 if(cycles)box.querySelector('.tool-chips').remove();let on=false,until=0,t0=0;const ball=box.querySelector('.breath-ball span'),total=()=>cycles?cycles*phases.reduce((n,p)=>n+p[1],0):minutes*60;
 box.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{minutes=Number(b.dataset.min);box.querySelectorAll('[data-min]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('brLeft').textContent=mmss(total())});
 let last=-1;every(()=>{if(!on)return;const el=(Date.now()-t0)/1000,left=total()-el;if(left<=0){on=false;$('brGo').textContent='▶ Outra vez';$('brPhase').textContent='Muito bem 🌿';ball.style.transform='scale(.55)';awake(false);tone(520,.8,.1);return}$('brLeft').textContent=mmss(Math.ceil(left));const cyc=phases.reduce((n,p)=>n+p[1],0);let at=el%cyc,i=0;while(at>=phases[i][1]){at-=phases[i][1];i++}const [name,len,scale]=phases[i];$('brPhase').textContent=name+' · '+Math.ceil(len-at);if(i!==last){last=i;ball.style.transitionDuration=len+'s';ball.style.transform='scale('+scale+')';tone(scale>.8?660:440,.1,.05);if($('brVoice').checked)speak(name)}},200);
 $('brGo').onclick=()=>{if(on){on=false;$('brGo').textContent='▶ Começar';awake(false);return}on=true;last=-1;t0=Date.now();$('brGo').textContent='■ Parar';awake(true)}}

const TOOLS={
// --- Relógios
stopwatch:{group:'Relógios',icon:'⏱',name:'Cronómetro',run(box){let start=0,acc=0,on=false,laps=[];box.innerHTML=`<p id="swClock" class="run-big tool-clock">00:00.0</p><div class="tool-row"><button id="swGo" class="primary">▶ Começar</button><button id="swLap" class="secondary" disabled>Volta</button><button id="swReset" class="secondary">Zerar</button></div><ol id="swLaps" class="tool-list"></ol>`;const now=()=>acc+(on?Date.now()-start:0),fmt=ms=>mmss(Math.floor(ms/1000))+'.'+Math.floor(ms%1000/100);
 every(()=>{$('swClock').textContent=fmt(now())},100);$('swGo').onclick=()=>{if(on){acc=now();on=false;awake(false)}else{start=Date.now();on=true;awake(true)}$('swGo').textContent=on?'❚❚ Parar':'▶ Continuar';$('swLap').disabled=!on};
 $('swLap').onclick=()=>{laps.unshift(now());$('swLaps').innerHTML=laps.map((t,i)=>`<li><span>Volta ${laps.length-i}</span><strong>${fmt(t-(laps[i+1]||0))}</strong><small>${fmt(t)}</small></li>`).join('')};$('swReset').onclick=()=>{acc=0;on=false;laps=[];$('swLaps').innerHTML='';$('swGo').textContent='▶ Começar';$('swLap').disabled=true;awake(false)}}},
timer:{group:'Relógios',icon:'⏲',name:'Temporizador',run(box){let total=60,left=60000,end=0,on=false,said=-1;box.innerHTML=`<div class="tool-chips">${[30,60,120,180,300,600].map(s=>`<button type="button" data-t="${s}">${s<60?s+' s':s/60+' min'}</button>`).join('')}</div><label class="tool-field">Ou escreve os minutos<input id="tmMin" type="number" min="1" max="180" inputmode="numeric" placeholder="Ex.: 7"></label><p id="tmClock" class="run-big tool-clock">01:00</p><div class="tool-row"><button id="tmGo" class="primary">▶ Começar</button><button id="tmReset" class="secondary">Repor</button></div>`;
 const show=()=>{$('tmClock').textContent=mmss(Math.ceil(left/1000))},set=s=>{total=s;left=s*1000;on=false;$('tmGo').textContent='▶ Começar';awake(false);show()};show();
 box.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>set(Number(b.dataset.t)));$('tmMin').onchange=()=>{const m=Number($('tmMin').value);if(m>=1&&m<=180)set(m*60)};
 every(()=>{if(!on)return;left=Math.max(0,end-Date.now());show();const s=Math.ceil(left/1000);if(s>0&&s<=3&&s!==said){said=s;tone(880,.12)}if(!left){on=false;$('tmGo').textContent='▶ Começar';tone(660,.9,.2);vib([300,150,300]);speak('Tempo!');awake(false)}},200);
 $('tmGo').onclick=()=>{if(on){on=false;left=Math.max(0,end-Date.now());awake(false)}else{if(!left)left=total*1000;end=Date.now()+left;on=true;awake(true)}$('tmGo').textContent=on?'❚❚ Pausar':'▶ Continuar'};$('tmReset').onclick=()=>set(total)}},
amrap:{group:'Relógios',icon:'🔁',name:'AMRAP',hint:'Máximo de rondas',run(box){let mins=10,end=0,on=false,rounds=0,lastMin=-1;const best=()=>extra().amrap?.[mins]||0;box.innerHTML=`<p class="style-intro">Faz o máximo de rondas possível no tempo escolhido. Toca em “+1 ronda” sempre que acabares uma.</p><div class="tool-chips">${[5,10,12,15,20].map(m=>`<button type="button" data-m="${m}" aria-pressed="${m===10}">${m} min</button>`).join('')}</div><p id="amClock" class="run-big tool-clock">10:00</p><button id="amRound" class="tool-tap tool-tap-small" type="button" disabled><span id="amN">0</span><small>rondas · toca para somar</small></button><div class="tool-row"><button id="amGo" class="primary">▶ Começar</button></div><p id="amBest" class="source-note"></p>`;
 const info=()=>{$('amBest').textContent=best()?`O teu melhor em ${mins} min: ${best()} rondas.`:''};info();
 box.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{if(on)return;mins=Number(b.dataset.m);box.querySelectorAll('[data-m]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('amClock').textContent=mmss(mins*60);info()});
 const stop=()=>{on=false;awake(false);$('amRound').disabled=true;$('amGo').textContent='▶ Outra vez';const x=extra();if(rounds>(x.amrap?.[mins]||0)){x.amrap={...(x.amrap||{}),[mins]:rounds};saveExtra(x);toast('🏆 Novo recorde: '+rounds+' rondas em '+mins+' min!')}info()};
 every(()=>{if(!on)return;const left=Math.max(0,Math.ceil((end-Date.now())/1000));$('amClock').textContent=mmss(left);const m=Math.ceil(left/60);if(left&&left%60===0&&m!==lastMin){lastMin=m;speak(m===1?'Falta 1 minuto':'Faltam '+m+' minutos');tone(700,.2)}if(!left){tone(520,1,.2);vib([400,200,400]);speak('Tempo! '+rounds+' rondas.');stop()}},250);
 $('amRound').onclick=()=>{rounds++;$('amN').textContent=rounds;vib(30);tone(900,.08,.08)};$('amGo').onclick=()=>{if(on){stop();return}rounds=0;$('amN').textContent='0';end=Date.now()+mins*60000;on=true;lastMin=mins;$('amRound').disabled=false;$('amGo').textContent='■ Terminar';awake(true);speak('Vai!')}}},
emom:{group:'Relógios',icon:'⏰',name:'EMOM',hint:'Uma tarefa por minuto',run(box){let on=false,t0=0,mins=10,lastMin=-1;box.innerHTML=`<p class="style-intro">No início de cada minuto fazes as repetições. O que sobrar do minuto é descanso.</p><div class="tool-form"><label class="tool-field">Minutos<input id="emMin" type="number" min="2" max="40" value="10" inputmode="numeric"></label><label class="tool-field">Minutos ímpares<input id="emA" maxlength="40" value="10 flexões"></label><label class="tool-field">Minutos pares<input id="emB" maxlength="40" value="15 agachamentos"></label></div><p id="emNow" class="tool-phase">Pronto?</p><p id="emClock" class="run-big tool-clock">01:00</p><div class="tool-row"><button id="emGo" class="primary">▶ Começar</button></div>`;
 const task=m=>((m%2?$('emA'):$('emB')).value||'').trim();
 every(()=>{if(!on)return;const el=Math.floor((Date.now()-t0)/1000),m=Math.floor(el/60)+1;if(m>mins){on=false;awake(false);$('emGo').textContent='▶ Outra vez';$('emNow').textContent='Feito! 💪';$('emClock').textContent='00:00';tone(520,1,.2);speak('Terminado. Bom trabalho!');return}$('emClock').textContent=mmss(60-el%60);if(m!==lastMin){lastMin=m;$('emNow').textContent='Minuto '+m+' de '+mins+': '+task(m);tone(880,.3,.18);vib(200);speak('Minuto '+m+'. '+task(m))}const s=60-el%60;if(s<=3&&s>0)tone(700,.06,.06)},1000);
 $('emGo').onclick=()=>{if(on){on=false;awake(false);$('emGo').textContent='▶ Começar';$('emNow').textContent='Parado';return}mins=Math.max(2,Math.min(40,Number($('emMin').value)||10));t0=Date.now();lastMin=-1;on=true;awake(true);$('emGo').textContent='■ Parar'}}},
metronome:{group:'Relógios',icon:'🎵',name:'Metrónomo',hint:'Para manter o ritmo',run(box){let on=false,beat=0,timer=null;box.innerHTML=`<p class="style-intro">Um som a cada batida, para fazeres as repetições sempre ao mesmo ritmo.</p><p id="mtBpm" class="run-big tool-clock">60</p><p class="tool-sub">batidas por minuto</p><input id="mtRange" type="range" min="30" max="180" value="60" aria-label="Batidas por minuto"><div class="tool-chips">${[40,60,80,100,120].map(v=>`<button type="button" data-bpm="${v}">${v}</button>`).join('')}</div><label class="tool-field">Acentuar a cada<select id="mtAccent">${options([[0,'Nenhuma'],[2,'2 batidas'],[3,'3 batidas'],[4,'4 batidas']])}</select></label><div class="tool-row"><button id="mtGo" class="primary">▶ Começar</button></div>`;
 const restart=()=>{clearInterval(timer);if(!on)return;const bpm=Number($('mtRange').value),acc=Number($('mtAccent').value);timer=setInterval(()=>{beat++;const strong=acc&&beat%acc===1;tone(strong?1200:800,.05,strong?.18:.1)},60000/bpm)};later(()=>clearInterval(timer));
 $('mtRange').oninput=()=>{$('mtBpm').textContent=$('mtRange').value;restart()};box.querySelectorAll('[data-bpm]').forEach(b=>b.onclick=()=>{$('mtRange').value=b.dataset.bpm;$('mtRange').oninput()});$('mtAccent').onchange=restart;$('mtGo').onclick=()=>{on=!on;beat=0;$('mtGo').textContent=on?'■ Parar':'▶ Começar';awake(on);restart()}}},
stretch:{group:'Relógios',icon:'🧘',name:'Alongar com tempo',hint:'Avisa quando trocar de lado',run(box){let on=false,t0=0,last='';box.innerHTML=`<p class="style-intro">Escolhe quanto tempo por lado. A app avisa quando trocar de lado e quando passar ao alongamento seguinte.</p><div class="tool-form"><label class="tool-field">Segundos por lado<select id="stSec">${options([[20,'20 s'],[30,'30 s'],[45,'45 s'],[60,'1 min']])}</select></label><label class="tool-field">Alongamentos<input id="stN" type="number" min="1" max="12" value="5" inputmode="numeric"></label><label class="tool-check"><input id="stBoth" type="checkbox" checked> Dos dois lados</label></div><p id="stNow" class="tool-phase">Pronto?</p><p id="stClock" class="run-big tool-clock">00:30</p><div class="tool-row"><button id="stGo" class="primary">▶ Começar</button></div>`;$('stSec').value='30';
 every(()=>{if(!on)return;const sec=Number($('stSec').value),both=$('stBoth').checked,n=Math.max(1,Math.min(12,Number($('stN').value)||5)),per=both?2:1,el=(Date.now()-t0)/1000,k=Math.floor(el/sec);if(k>=n*per){on=false;awake(false);$('stGo').textContent='▶ Outra vez';$('stNow').textContent='Terminado 🌿';$('stClock').textContent='00:00';tone(520,1,.15);speak('Terminado.');return}const which=Math.floor(k/per)+1,side=both?(k%per?'lado direito':'lado esquerdo'):'',label='Alongamento '+which+' de '+n+(side?' · '+side:'');$('stNow').textContent=label;$('stClock').textContent=mmss(Math.ceil(sec-el%sec));if(label!==last){const first=!last;last=label;tone(760,.25,.15);vib(150);speak(first?'Começa. '+(side||''):side==='lado direito'?'Troca de lado.':'Próximo alongamento.'+(side?' '+side:''))}},250);
 $('stGo').onclick=()=>{if(on){on=false;awake(false);$('stGo').textContent='▶ Começar';return}t0=Date.now();last='';on=true;awake(true);$('stGo').textContent='■ Parar'}}},
// --- Contar
counter:{group:'Contar',icon:'👆',name:'Contador de repetições',run(box){let n=0;box.innerHTML=`<button id="ctTap" class="tool-tap" type="button"><span id="ctN">0</span><small>Toca para contar</small></button><div class="tool-row"><button id="ctMinus" class="secondary">−1</button><button id="ctReset" class="secondary">Zerar</button><label class="tool-check"><input id="ctVoice" type="checkbox"> Dizer em voz alta</label></div>`;const show=()=>{$('ctN').textContent=n};
 $('ctTap').onclick=()=>{n++;show();vib(20);tone(900,.06,.06);if($('ctVoice').checked)speak(String(n))};$('ctMinus').onclick=()=>{n=Math.max(0,n-1);show()};$('ctReset').onclick=()=>{n=0;show()}}},
pulse:{group:'Contar',icon:'❤️',name:'Medir a pulsação',hint:'Toca a cada batimento',run(box){let taps=[];box.innerHTML=`<p class="style-intro">Põe dois dedos no pulso ou no pescoço e toca no botão a cada batimento, durante uns 15 segundos.</p><button id="puTap" class="tool-tap" type="button"><span id="puN">—</span><small>batimentos por minuto</small></button><p id="puInfo" class="source-note">Toca para começar.</p>`;
 $('puTap').onclick=()=>{const now=Date.now();if(taps.length&&now-taps.at(-1)>3000)taps=[];taps.push(now);taps=taps.slice(-16);vib(15);if(taps.length<4){$('puInfo').textContent='Continua a tocar…';return}const gaps=taps.slice(1).map((t,i)=>t-taps[i]).sort((a,b)=>a-b),mid=gaps[Math.floor(gaps.length/2)],bpm=Math.round(60000/mid);$('puN').textContent=bpm;if(taps.length>=10&&window.Habits&&!document.getElementById('puSave')){$('puInfo').insertAdjacentHTML('afterend','<button id="puSave" class="secondary extra-wide" type="button">❤️ Guardar como pulsação em repouso</button>');document.getElementById('puSave').onclick=()=>{window.Habits.saveRestingPulse(Number($('puN').textContent));toast('❤️ Guardado em Início → Passos e corpo.')}}$('puInfo').textContent=taps.length<10?'Mais uns toques para ficar certo.':bpm<60?'Pulsação calma.':bpm<100?'Pulsação normal em repouso.':'Pulsação alta: se estás em repouso, descansa e volta a medir.'}}},
// --- Treinos rápidos
express:{group:'Treinos rápidos',icon:'⚡',name:'Treino de 5 minutos',hint:'Sem material',start(){startWorkout('Treino de 5 minutos',P.express(),{noWarmup:true})}},
generator:{group:'Treinos rápidos',icon:'🪄',name:'Criar um treino',hint:'Tempo, zona e material',run(box){let seed=Date.now(),items=[];box.innerHTML=`<div class="tool-form"><label class="tool-field">Zona do corpo<select id="gnZone">${options(Object.entries(P.zones))}</select></label><label class="tool-field">Tempo<select id="gnMin">${options([[5,'5 min'],[10,'10 min'],[15,'15 min'],[20,'20 min'],[30,'30 min'],[45,'45 min']])}</select></label><label class="tool-check"><input id="gnBar" type="checkbox"> Tenho barra</label><label class="tool-check"><input id="gnDb" type="checkbox"> Tenho halteres</label><label class="tool-check"><input id="gnQuiet" type="checkbox"> Sem saltos</label></div><details class="gen-skip"><summary>🚫 Exercícios que não queres</summary><div id="gnSkip" class="tool-chips"></div></details><div id="gnList"></div><div class="tool-row"><button id="gnGo" class="primary">▶ Começar</button><button id="gnNew" class="secondary">🔀 Outro</button><button id="gnKeep" class="secondary">💾 Guardar</button></div>`;
 const pref=local('cal_ui_gen',{});$('gnZone').value=pref.zone||'full';$('gnMin').value=String(pref.minutes||20);$('gnBar').checked=!!pref.bar;$('gnDb').checked=!!pref.dumbbells;$('gnQuiet').checked=!!pref.quiet;if(box.dataset.zone)$('gnZone').value=box.dataset.zone;
 const make=()=>{const o={zone:$('gnZone').value,minutes:Number($('gnMin').value),bar:$('gnBar').checked,dumbbells:$('gnDb').checked,quiet:$('gnQuiet').checked};setLocal('cal_ui_gen',o);const no=local('cal_ui_gen_no',[]);items=P.generate({...o,seed},id=>byId.has(id)&&!no.includes(id));$('gnSkip').innerHTML=[...new Set(Object.values(P.pools).flat().map(p=>p[0]))].filter(id=>byId.has(id)).map(id=>`<button type="button" data-skip="${esc(id)}" aria-pressed="${no.includes(id)}">${no.includes(id)?'🚫 ':''}${esc(title(id))}</button>`).join('');$('gnList').innerHTML=`<ol class="tool-list tool-plan">${items.map(i=>`<li>${window.ExecutionMedia?ExecutionMedia.thumb(byId.get(i.id),esc,'tool-thumb'):''}<span><strong>${esc(title(i.id))}</strong><small>${i.sets} × ${i.reps} ${i.unit==='s'?'s':'reps'} · descanso ${i.rest} s</small></span></li>`).join('')}</ol><p class="source-note">Cerca de ${Math.round(P.seconds(items)/60)} min.</p>`};
 box.addEventListener('change',make);$('gnSkip').onclick=e=>{const b=e.target.closest('[data-skip]');if(!b)return;const id=b.dataset.skip,no=local('cal_ui_gen_no',[]);setLocal('cal_ui_gen_no',no.includes(id)?no.filter(x=>x!==id):[...no,id]);make()};make();$('gnNew').onclick=()=>{seed=Date.now();make()};$('gnGo').onclick=()=>startWorkout(P.zones[$('gnZone').value]+' · '+$('gnMin').value+' min',items);$('gnKeep').onclick=()=>{app.addSaved?.({id:Date.now().toString(36)+Math.random().toString(36).slice(2,8),name:(P.zones[$('gnZone').value]+' '+$('gnMin').value+' min').slice(0,60),items:structuredClone(items)});toast('Guardado nos teus planos.')}}},
ladder:{group:'Treinos rápidos',icon:'🪜',name:'Escada',hint:'1, 2, 3… até ao topo',run(box){box.innerHTML=`<p class="style-intro">Fazes 1 repetição, descansas, depois 2, depois 3… até ao topo.</p><div class="tool-form"><label class="tool-field">Exercício${moveSelect('ldId')}</label><label class="tool-field">Até<input id="ldTop" type="number" min="2" max="30" value="8" inputmode="numeric"></label><label class="tool-field">Descanso (s)<input id="ldRest" type="number" min="0" max="180" value="20" inputmode="numeric"></label></div><p id="ldInfo" class="tool-out"></p><div class="tool-row"><button id="ldGo" class="primary">▶ Começar</button></div>`;
 const items=()=>{const o=$('ldId').selectedOptions[0];return P.ladder(o.value,o.dataset.unit,Number($('ldTop').value)||8,Math.max(0,Math.min(180,Number($('ldRest').value)||0)))};const info=()=>{const l=items(),u=l[0].unit==='s'?' s':' repetições';$('ldInfo').textContent=l.length+' degraus · '+l.reduce((n,i)=>n+i.reps,0)+u+' no total'};box.addEventListener('input',info);box.addEventListener('change',info);info();$('ldGo').onclick=()=>startWorkout('Escada de '+title($('ldId').value),items(),{noWarmup:false})}},
pyramid:{group:'Treinos rápidos',icon:'🔺',name:'Pirâmide',hint:'Sobe e desce',run(box){box.innerHTML=`<p class="style-intro">Sobe de 1 até ao topo e volta a descer: 1, 2, 3… 3, 2, 1.</p><div class="tool-form"><label class="tool-field">Exercício${moveSelect('pyId')}</label><label class="tool-field">Topo<input id="pyTop" type="number" min="2" max="20" value="5" inputmode="numeric"></label><label class="tool-field">Descanso (s)<input id="pyRest" type="number" min="0" max="180" value="20" inputmode="numeric"></label></div><p id="pyInfo" class="tool-out"></p><div class="tool-row"><button id="pyGo" class="primary">▶ Começar</button></div>`;
 const items=()=>{const o=$('pyId').selectedOptions[0];return P.ladder(o.value,o.dataset.unit,Number($('pyTop').value)||5,Math.max(0,Math.min(180,Number($('pyRest').value)||0)),true)};const info=()=>{const l=items(),u=l[0].unit==='s'?' s':' repetições';$('pyInfo').textContent=l.length+' séries · '+l.reduce((n,i)=>n+i.reps,0)+u+' no total'};box.addEventListener('input',info);box.addEventListener('change',info);info();$('pyGo').onclick=()=>startWorkout('Pirâmide de '+title($('pyId').value),items())}},
cards:{group:'Treinos rápidos',icon:'🃏',name:'Treino de cartas',hint:'O naipe escolhe o exercício',run(box){const map={'♥':'Pushups','♦':'Bodyweight_Squat','♣':'Crunches','♠':'Bodyweight_Walking_Lunge'};let deck=[],done=[],t0=0,card=null;box.innerHTML=`<p class="style-intro">Tira uma carta, faz o exercício do naipe com tantas repetições como o valor (figuras valem 10, o ás vale 11).</p><div class="card-legend">${Object.entries(map).map(([s,id])=>`<span><b class="${s==='♥'||s==='♦'?'is-red':''}">${s}</b>${esc(title(id))}</span>`).join('')}</div><div id="cdCard" class="play-card" aria-live="polite"><span>?</span></div><p id="cdInfo" class="tool-out"></p><div class="tool-row"><button id="cdGo" class="primary">🃏 Baralho inteiro</button><button id="cdHalf" class="secondary">Meio baralho</button></div><div class="tool-row"><button id="cdDone" class="primary" hidden>✓ Feito · próxima carta</button><button id="cdEnd" class="secondary" hidden>Terminar e guardar</button></div>`;
 const show=()=>{const left=deck.length,reps=done.reduce((n,c)=>n+c.reps,0);$('cdInfo').textContent=card?`${card.reps} × ${title(map[card.suit])} · faltam ${left} cartas · ${reps} repetições feitas`:'';$('cdCard').innerHTML=card?`<b class="${card.suit==='♥'||card.suit==='♦'?'is-red':''}">${card.label}</b><span class="${card.suit==='♥'||card.suit==='♦'?'is-red':''}">${card.suit}</span><small>${esc(title(map[card.suit]))}</small>`:'<span>?</span>'};
 const begin=half=>{deck=P.deck(half);done=[];t0=Date.now();card=deck.shift();$('cdDone').hidden=false;$('cdEnd').hidden=false;$('cdGo').hidden=true;$('cdHalf').hidden=true;show();speak(card.reps+' '+title(map[card.suit]))};
 const end=()=>{if(done.length&&app.saveRun){app.saveRun({id:crypto.randomUUID(),name:'Treino de cartas',records:done.map(c=>({id:map[c.suit],unit:'reps',reps:c.reps,weight:0})),startedAt:t0,calendarId:null});window.dispatchEvent(new Event('training-updated'));toast('Guardado no histórico: '+done.length+' cartas.')}card=null;deck=[];$('cdDone').hidden=true;$('cdEnd').hidden=true;$('cdGo').hidden=false;$('cdHalf').hidden=false;show();$('cdInfo').textContent=done.length?'Bom trabalho! 💪':''};
 $('cdGo').onclick=()=>begin(false);$('cdHalf').onclick=()=>begin(true);$('cdDone').onclick=()=>{done.push(card);vib(30);card=deck.shift()||null;if(!card){speak('Baralho terminado!');end();return}show();speak(card.reps+' '+title(map[card.suit]))};$('cdEnd').onclick=end}},
dice:{group:'Treinos rápidos',icon:'🎲',name:'Dado do treino',hint:'A sorte escolhe',run(box){const faces=['⚀','⚁','⚂','⚃','⚄','⚅'],list=['Pushups','Bodyweight_Squat','Crunches','Butt_Lift_Bridge','Bodyweight_Walking_Lunge','Plank'].filter(id=>byId.has(id));let pick=null;box.innerHTML=`<p class="style-intro">Um dado escolhe o exercício e o outro as repetições (vezes 5).</p><div class="dice-row"><span id="dcA" class="die">🎲</span><span id="dcB" class="die">🎲</span></div><p id="dcOut" class="tool-out"></p><div class="tool-row"><button id="dcRoll" class="primary">🎲 Lançar</button><button id="dcGo" class="secondary" hidden>▶ Fazer agora</button></div><ol class="tool-list dice-key">${list.map((id,i)=>`<li><span>${faces[i]}</span><strong>${esc(title(id))}</strong></li>`).join('')}</ol>`;
 $('dcRoll').onclick=()=>{let n=0;const spin=setInterval(()=>{$('dcA').textContent=faces[Math.floor(Math.random()*6)];$('dcB').textContent=faces[Math.floor(Math.random()*6)];if(++n>8){clearInterval(spin);const a=Math.floor(Math.random()*list.length),b=Math.floor(Math.random()*6);$('dcA').textContent=faces[a];$('dcB').textContent=faces[b];const id=list[a],timed=id==='Plank',amount=(b+1)*(timed?10:5);pick={id,sets:1,reps:amount,rest:30,unit:timed?'s':'reps'};$('dcOut').textContent=amount+(timed?' s de ':' × ')+title(id);$('dcGo').hidden=false;vib(40);speak($('dcOut').textContent)}},70);later(()=>clearInterval(spin))};$('dcGo').onclick=()=>pick&&startWorkout('Dado do treino',[pick],{noWarmup:true})}},
daily:{group:'Treinos rápidos',icon:'🎯',name:'Desafio do dia',hint:'Um novo todos os dias',run(box){const draw=()=>{const d=today(),c=P.daily(d),x=extra(),days=x.daily||{},n=P.streak(days,d);box.innerHTML=`<div class="daily-card">${window.ExecutionMedia?ExecutionMedia.thumb(byId.get(c.id),esc,'tool-thumb tool-thumb-big'):''}<p class="extra-label">HOJE</p><h3>${esc(c.text)}</h3><p class="source-note">Divide como quiseres ao longo do dia.</p></div>${days[d]?'<p class="extra-today">✓ Feito hoje. Até amanhã!</p>':'<button id="dyDone" class="primary extra-wide">✓ Já fiz</button>'}<p class="tool-out">${n?`🔥 ${n} ${n===1?'dia seguido':'dias seguidos'}`:'Começa hoje uma série de dias seguidos.'}</p><button id="dyGo" class="secondary extra-wide">▶ Fazer agora numa série</button>`;
 if($('dyDone'))$('dyDone').onclick=()=>{const x=extra();x.daily=lastDays({...(x.daily||{}),[d]:true});saveExtra(x);vib([60,40,60]);draw()};$('dyGo').onclick=()=>startWorkout('Desafio do dia',[{id:c.id,sets:1,reps:Math.min(300,c.reps),rest:30,unit:c.unit}],{noWarmup:true})};draw()}},
gtg:{group:'Treinos rápidos',icon:'🧈',name:'Pouco e muitas vezes',hint:'Séries leves ao longo do dia',run(box){const draw=()=>{const g={exercise:'Pushups',max:10,days:{},...(extra().gtg||{})},d=today(),sets=g.days[d]||0,size=P.gtgSet(g.max);box.innerHTML=`<p class="style-intro">Faz várias séries fáceis ao longo do dia (metade do teu máximo), com pelo menos uma hora entre elas. É uma forma suave de subir o teu máximo.</p><div class="tool-form"><label class="tool-field">Exercício${moveSelect('gtId',g.exercise,'reps')}</label><label class="tool-field">O teu máximo<input id="gtMax" type="number" min="1" max="200" value="${g.max}" inputmode="numeric"></label></div><div class="tool-out"><strong>Séries de ${size}</strong> · objetivo de 5 a 8 por dia</div><button id="gtAdd" class="tool-tap tool-tap-small" type="button"><span>${sets}</span><small>séries hoje · toca quando fizeres uma</small></button><p class="source-note">Hoje: ${sets*size} repetições. Para sem chegar ao cansaço.</p>`;
 const save=patch=>{const x=extra();x.gtg={...g,...patch,days:lastDays({...g.days,...(patch.days||{})},60)};saveExtra(x);draw()};$('gtId').onchange=()=>save({exercise:$('gtId').value});$('gtMax').onchange=()=>{const v=Math.round(Number($('gtMax').value));if(v>=1&&v<=200)save({max:v})};$('gtAdd').onclick=()=>{vib(30);save({days:{[d]:sets+1}})}};draw()}},
// --- Calculadoras
foodcam:{group:'Calculadoras',icon:'📷',name:'Calorias pela câmara',hint:'Foto do prato ou código de barras',start(){window.FoodCam?.open()}},
onerm:{group:'Calculadoras',icon:'🏋️',name:'Força máxima (1RM)',hint:'Para barra ou fundos com peso',run(box){bodyForm(box,['weight'],()=>'');box.querySelector('.tool-form').insertAdjacentHTML('beforeend','<label class="tool-field">Peso extra (kg)<input id="rmExtra" type="number" min="0" max="300" step="0.5" value="0" inputmode="decimal"></label><label class="tool-field">Repetições feitas<input id="rmReps" type="number" min="1" max="15" value="5" inputmode="numeric"></label>');
 const calc=()=>{const w=Number(box.querySelector('[data-body=weight]').value)||0,extraKg=Number($('rmExtra').value)||0,reps=Number($('rmReps').value)||0,total=P.oneRM(w+extraKg,reps);if(!total||!w){$('calcOut').innerHTML='<p class="source-note">Preenche o teu peso, o peso extra e as repetições.</p>';return}const extra1=Math.max(0,P.oneRM(w+extraKg,reps)-w);$('calcOut').innerHTML=`<p><strong>${extra1.toFixed(1)} kg extra</strong> numa repetição máxima (total ${total} kg com o corpo).</p><table class="tool-table"><thead><tr><th>Repetições</th><th>Peso extra</th></tr></thead><tbody>${[3,5,8,10].map(r=>`<tr><td>${r}</td><td>${Math.max(0,total/(1+r/30)-w).toFixed(1)} kg</td></tr>`).join('')}</tbody></table>`};box.addEventListener('input',calc);calc()}},
frommax:{group:'Calculadoras',icon:'📋',name:'Séries pelo teu máximo',hint:'Diz o máximo, a app faz as séries',run(box){box.innerHTML=`<div class="tool-form"><label class="tool-field">Exercício${moveSelect('fmId')}</label><label class="tool-field">Máximo seguido<input id="fmMax" type="number" min="1" max="300" value="10" inputmode="numeric"></label></div><div id="fmOut"></div>`;
 const draw=()=>{const o=$('fmId').selectedOptions[0],max=Number($('fmMax').value)||0,u=o.dataset.unit;$('fmOut').innerHTML=P.fromMax(max).map((p,i)=>`<div class="tool-option"><div><strong>${p.name}: ${p.sets} × ${p.reps}${u==='s'?' s':''}</strong><small>${p.text} · descanso ${p.rest} s</small></div><button class="secondary" data-fm="${i}">▶ Começar</button></div>`).join('')};
 box.addEventListener('input',draw);box.addEventListener('change',draw);draw();$('fmOut').onclick=e=>{const b=e.target.closest('[data-fm]');if(!b)return;const o=$('fmId').selectedOptions[0],p=P.fromMax(Number($('fmMax').value))[Number(b.dataset.fm)];startWorkout(p.name+' · '+title(o.value),[{id:o.value,sets:p.sets,reps:Math.min(300,p.reps),rest:p.rest,unit:o.dataset.unit}])}}},
bmi:{group:'Calculadoras',icon:'⚖️',name:'IMC',hint:'Índice de massa corporal',run(box){bodyForm(box,['height','weight'],v=>{const r=P.bmi(v.weight,v.height);return r?`<p class="tool-big">${r}</p><p><strong>${P.bmiLabel(r)}</strong></p><p class="source-note">O IMC não distingue músculo de gordura: quem treina força pode ter um valor alto sem excesso de gordura.</p>`:''})}},
fat:{group:'Calculadoras',icon:'📏',name:'Gordura corporal',hint:'Com uma fita métrica',run(box){bodyForm(box,['sex','height','waist','neck','hip'],v=>{const r=P.navyFat(v);return r?`<p class="tool-big">${r}%</p><p class="source-note">Método da Marinha dos EUA: mede a cintura à altura do umbigo e o pescoço abaixo da maçã de Adão.${v.sex==='f'?' Nas mulheres usa também a anca.':''}</p>`:''})}},
calories:{group:'Calculadoras',icon:'🔥',name:'Calorias por dia',hint:'Para manter, perder ou ganhar',run(box){bodyForm(box,['sex','age','height','weight','activity'],v=>{const r=P.calories(v);return r?`<p class="tool-big">${r.keep} kcal</p><p>para manter o peso</p><ul class="tool-list"><li><span>Para perder devagar</span><strong>${r.lose} kcal</strong></li><li><span>Para ganhar músculo</span><strong>${r.gain} kcal</strong></li><li><span>Em repouso total</span><strong>${r.base} kcal</strong></li></ul>`:''})}},
protein:{group:'Calculadoras',icon:'🥚',name:'Proteína por dia',run(box){bodyForm(box,['weight'],v=>{const r=P.protein(v.weight);return r?`<p class="tool-big">${r.low}–${r.high} g</p><p>de proteína por dia, para quem treina força.</p><p class="source-note">Cerca de ${r.meal} g por refeição em 4 refeições. Ex.: 150 g de frango ≈ 45 g; 3 ovos ≈ 18 g; 200 g de skyr ≈ 20 g.</p>`:''})}},
water:{group:'Calculadoras',icon:'💧',name:'Água por dia',run(box){bodyForm(box,['weight','minutes'],v=>{const r=P.water(v.weight,v.minutes||0);return r?`<p class="tool-big">${(r/1000).toLocaleString('pt-PT',{maximumFractionDigits:1})} L</p><p>cerca de ${Math.round(r/250)} copos de 250 ml.</p><p class="source-note">Bebe mais quando está calor ou transpiras muito.</p>`:''})}},
zones:{group:'Calculadoras',icon:'💓',name:'Zonas de pulsação',run(box){bodyForm(box,['age','rest'],v=>{const r=P.hrZones(v.age,v.rest||0);return r?`<p>Pulsação máxima estimada: <strong>${r.max}</strong></p><ul class="tool-list">${r.zones.map(z=>`<li><span>${z.name}</span><strong>${z.from}–${z.to}</strong></li>`).join('')}</ul>`:''})}},
convert:{group:'Calculadoras',icon:'🔄',name:'Conversor',hint:'kg, libras, cm, polegadas',run(box){const pairs=[['kg','lb',2.20462],['cm','polegadas',.393701],['km','milhas',.621371]];box.innerHTML=pairs.map(([a,b],i)=>`<div class="tool-pair"><label class="tool-field">${a}<input data-pa="${i}" type="number" inputmode="decimal" step="any"></label><span aria-hidden="true">⇄</span><label class="tool-field">${b}<input data-pb="${i}" type="number" inputmode="decimal" step="any"></label></div>`).join('');
 box.addEventListener('input',e=>{const t=e.target,i=Number(t.dataset.pa??t.dataset.pb),f=pairs[i]?.[2];if(f==null)return;const v=Number(t.value);const other=box.querySelector(t.dataset.pa!=null?`[data-pb="${i}"]`:`[data-pa="${i}"]`);other.value=t.value===''?'':String(Math.round((t.dataset.pa!=null?v*f:v/f)*100)/100)})}},
// --- Bem-estar
watercount:{group:'Bem-estar',icon:'🥤',name:'Copos de água hoje',run(box){const draw=()=>{const x=extra(),w=x.water||{},d=today(),n=w[d]||0,goal=Math.max(4,Math.round((P.water(body().weight)||2000)/250)),week=Array.from({length:7},(_,i)=>P.addDays(d,i-6));box.innerHTML=`<button id="wcAdd" class="tool-tap" type="button"><span>${n}</span><small>de ${goal} copos · toca quando beberes</small></button><progress class="tool-progress" max="${goal}" value="${Math.min(goal,n)}"></progress><div class="tool-row"><button id="wcMinus" class="secondary">−1 copo</button></div><div class="week-bars" aria-label="Últimos 7 dias">${week.map(day=>`<span style="--h:${Math.min(1,(w[day]||0)/goal)}"><i></i><small>${new Date(day+'T12:00:00').toLocaleDateString('pt-PT',{weekday:'narrow'})}</small></span>`).join('')}</div><p class="source-note">Um copo = 250 ml. O objetivo vem do teu peso.</p>`;
 const set=v=>{const x=extra();x.water=lastDays({...(x.water||{}),[d]:Math.max(0,Math.min(40,v))},60);saveExtra(x);draw()};$('wcAdd').onclick=()=>{vib(20);set(n+1);if(n+1===goal)toast('💧 Objetivo de água atingido!')};$('wcMinus').onclick=()=>set(n-1)};draw()}},
box:{group:'Bem-estar',icon:'🟦',name:'Respiração quadrada',hint:'4 tempos para acalmar',run(box){breathe(box,[['Inspira',4,1],['Aguenta',4,1],['Expira',4,.55],['Aguenta',4,.55]])}},
sleep478:{group:'Bem-estar',icon:'🌙',name:'Respirar para dormir',hint:'4-7-8',run(box){breathe(box,[['Inspira',4,1],['Aguenta',7,1],['Expira',8,.55]],{cycles:4})}},
sleep:{group:'Bem-estar',icon:'😴',name:'Diário de sono',run(box){const draw=()=>{const s=extra().sleep||{},d=today(),week=Array.from({length:7},(_,i)=>P.addDays(d,i-6)),vals=week.map(x=>s[x]).filter(Boolean),avg=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*10)/10:0;box.innerHTML=`<p class="style-intro">Quantas horas dormiste esta noite?</p><div class="tool-chips">${[5,5.5,6,6.5,7,7.5,8,8.5,9,10].map(h=>`<button type="button" data-h="${h}" aria-pressed="${s[d]===h}">${String(h).replace('.',',')} h</button>`).join('')}</div><div class="week-bars" aria-label="Últimos 7 dias">${week.map(day=>`<span style="--h:${Math.min(1,(s[day]||0)/10)}"><i></i><small>${new Date(day+'T12:00:00').toLocaleDateString('pt-PT',{weekday:'narrow'})}</small></span>`).join('')}</div><p class="tool-out">${avg?`Média dos últimos 7 dias: <strong>${String(avg).replace('.',',')} h</strong>. ${avg<7?'Dormir pouco atrasa a recuperação: nesses dias faz um treino mais leve.':'Bom descanso para recuperar.'}`:'Regista a tua noite para veres a média.'}</p>`;box.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{const x=extra();x.sleep=lastDays({...(x.sleep||{}),[d]:Number(b.dataset.h)},60);saveExtra(x);draw()})};draw()}},
sore:{group:'Bem-estar',icon:'🩹',name:'O que me dói hoje',hint:'E o que posso treinar',run(box){const areas=[['legs','Pernas'],['upper','Peito e braços'],['back','Costas'],['core','Abdominais'],['shoulders','Ombros']];const draw=()=>{const s=extra().sore||{},d=today(),on=new Set(s.date===d?s.areas:[]),free=Object.keys(P.zones).filter(z=>z==='full'?!on.size:!(z==='legs'&&on.has('legs'))&&!(z==='upper'&&(on.has('upper')||on.has('back')||on.has('shoulders')))&&!(z==='core'&&on.has('core')));box.innerHTML=`<p class="style-intro">Marca as zonas com dores musculares (as normais depois do treino).</p><div class="tool-chips">${areas.map(([k,l])=>`<button type="button" data-area="${k}" aria-pressed="${on.has(k)}">${l}</button>`).join('')}</div><div class="tool-out">${on.size?(free.length?`Hoje podes treinar: <strong>${free.map(z=>P.zones[z]).join(', ')}</strong>.`:'Hoje é melhor descansar ou fazer só mobilidade.'):'Sem dores? Podes treinar o corpo todo.'}</div>${free.length?`<div class="tool-row">${free.slice(0,2).map(z=>`<button class="secondary" data-gen="${z}">🪄 Treino de ${P.zones[z].toLowerCase()}</button>`).join('')}</div>`:''}<p class="source-note">Dor forte, pontada ou dor nas articulações não é dor muscular: para e fala com um profissional de saúde.</p>`;
 box.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{const k=b.dataset.area;on.has(k)?on.delete(k):on.add(k);const x=extra();x.sore={date:d,areas:[...on]};saveExtra(x);draw()});box.querySelectorAll('[data-gen]').forEach(b=>b.onclick=()=>{const zone=b.dataset.gen;open('generator');const g=$('gnZone');if(g){g.value=zone;g.dispatchEvent(new Event('change',{bubbles:true}))}})};draw()}},
rest:{group:'Relógios',icon:'⏸',name:'Descanso entre séries',hint:'Para treinos fora da app',run(box){let end=0,on=false,sets=0,rest=90;box.innerHTML=`<p class="style-intro">Para quando treinas sem um plano: toca em “Série feita” e o descanso começa sozinho.</p><div class="tool-chips">${[45,60,90,120,180].map(s=>`<button type="button" data-r="${s}" aria-pressed="${s===90}">${s<60?s+' s':s%60?Math.floor(s/60)+':'+String(s%60).padStart(2,'0'):s/60+' min'}</button>`).join('')}</div><p id="rsClock" class="run-big tool-clock">01:30</p><p id="rsInfo" class="tool-sub">0 séries feitas</p><button id="rsDone" class="tool-tap tool-tap-small" type="button"><span>✓</span><small>Série feita · começa o descanso</small></button><div class="tool-row"><button id="rsSkip" class="secondary">Saltar descanso</button><button id="rsReset" class="text-button">Zerar</button></div>`;
 box.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{rest=Number(b.dataset.r);box.querySelectorAll('[data-r]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(!on)$('rsClock').textContent=mmss(rest)});
 let said=-1;every(()=>{if(!on)return;const left=Math.max(0,Math.ceil((end-Date.now())/1000));$('rsClock').textContent=mmss(left);if(left<=3&&left>0&&left!==said){said=left;tone(880,.12)}if(!left){on=false;awake(false);tone(660,.9,.2);vib([300,150,300]);speak('Vamos à próxima série!')}},250);
 $('rsDone').onclick=()=>{sets++;$('rsInfo').textContent=sets+(sets===1?' série feita':' séries feitas');end=Date.now()+rest*1000;on=true;awake(true);vib(40)};$('rsSkip').onclick=()=>{on=false;$('rsClock').textContent='00:00';awake(false)};$('rsReset').onclick=()=>{sets=0;on=false;$('rsInfo').textContent='0 séries feitas';$('rsClock').textContent=mmss(rest);awake(false)}}},
warmupmaker:{group:'Treinos rápidos',icon:'🔥',name:'Aquecimento à medida',hint:'Para o que vais treinar',run(box){box.innerHTML=`<div class="tool-chips">${[['full','Corpo todo'],['legs','Pernas'],['upper','Parte de cima']].map(([k,l],i)=>`<button type="button" data-wz="${k}" aria-pressed="${!i}">${l}</button>`).join('')}</div><div id="wzList"></div><div class="tool-row"><button id="wzGo" class="primary">▶ Aquecer agora</button></div>`;let zone='full';const draw=()=>{const items=P.warmup(zone).filter(i=>byId.has(i.id));$('wzList').innerHTML=`<ol class="tool-list tool-plan">${items.map(i=>`<li>${window.ExecutionMedia?ExecutionMedia.thumb(byId.get(i.id),esc,'tool-thumb'):''}<span><strong>${esc(title(i.id))}</strong><small>${i.reps} ${i.unit==='s'?'s':'repetições'}</small></span></li>`).join('')}</ol><p class="source-note">Cerca de ${Math.max(2,Math.round(P.seconds(items)/60))} minutos.</p>`};box.querySelectorAll('[data-wz]').forEach(b=>b.onclick=()=>{zone=b.dataset.wz;box.querySelectorAll('[data-wz]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()});draw();$('wzGo').onclick=()=>startWorkout('Aquecimento',P.warmup(zone),{noWarmup:true})}},
hotel:{group:'Treinos rápidos',icon:'🧳',name:'Treino de viagem',hint:'15 min num quarto, sem saltos',start(){startWorkout('Treino de viagem',P.hotel(),{noWarmup:false})}},
planktest:{group:'Testes',icon:'⏳',name:'Teste de prancha',hint:'Quanto tempo aguentas?',run(box){let t0=0,on=false;const draw=()=>{const x=extra().maxTests?.plank||[],best=x.reduce((m,r)=>Math.max(m,r.v),0);box.innerHTML=`<p class="style-intro">Põe-te em prancha e carrega em começar. Para quando a anca começar a cair.</p><p id="ptClock" class="run-big tool-clock">00:00</p><div class="tool-row"><button id="ptGo" class="primary">▶ Começar</button></div><p class="tool-out">${best?`🏆 O teu recorde: <strong>${mmss(best)}</strong>`:'Ainda sem recorde. Este é o primeiro!'}</p>${x.length?`<ul class="tool-list">${x.slice(-5).reverse().map(r=>`<li><span>${new Date(r.d+'T12:00:00').toLocaleDateString('pt-PT',{day:'numeric',month:'short'})}</span><strong>${mmss(r.v)}</strong></li>`).join('')}</ul>`:''}`;$('ptGo').onclick=()=>{if(on){on=false;awake(false);const v=Math.round((Date.now()-t0)/1000);if(v<3){draw();return}const y=extra(),list=[...(y.maxTests?.plank||[]),{d:today(),v}].slice(-30),was=best;y.maxTests={...(y.maxTests||{}),plank:list};saveExtra(y);if(v>was&&was)toast('🏆 Novo recorde de prancha: '+mmss(v)+'!');draw();return}t0=Date.now();on=true;awake(true);$('ptGo').textContent='■ Parei';speak('Vai!')}};every(()=>{if(on)$('ptClock').textContent=mmss((Date.now()-t0)/1000)},250);draw()}},
pushtest:{group:'Testes',icon:'💯',name:'Flexões num minuto',hint:'Toca a cada flexão',run(box){let end=0,on=false,n=0;const draw=()=>{const x=extra().maxTests?.push1||[],best=x.reduce((m,r)=>Math.max(m,r.v),0);box.innerHTML=`<p class="style-intro">Faz o máximo de flexões bem feitas em 1 minuto. Toca no botão a cada flexão (ou pede a alguém).</p><p id="p1Clock" class="run-big tool-clock">01:00</p><button id="p1Tap" class="tool-tap tool-tap-small" type="button" disabled><span id="p1N">0</span><small>flexões · toca a cada uma</small></button><div class="tool-row"><button id="p1Go" class="primary">▶ Começar</button></div><p class="tool-out">${best?`🏆 O teu recorde: <strong>${best} flexões</strong>`:'Ainda sem recorde.'}</p>`;
 const stop=()=>{on=false;awake(false);tone(520,1,.2);vib([300,150,300]);speak(n+' flexões!');const y=extra(),list=[...(y.maxTests?.push1||[]),{d:today(),v:n}].slice(-30);y.maxTests={...(y.maxTests||{}),push1:list};saveExtra(y);if(n>best&&best)toast('🏆 Novo recorde: '+n+' flexões num minuto!');setTimeout(draw,1500)};
 $('p1Go').onclick=()=>{if(on)return;n=0;end=Date.now()+60000;on=true;awake(true);$('p1Tap').disabled=false;$('p1Go').disabled=true;speak('Vai!')};$('p1Tap').onclick=()=>{if(!on)return;n++;$('p1N').textContent=n;vib(20);tone(900,.05,.06)};later(()=>{on=false})};
 every(()=>{if(!on)return;const left=Math.max(0,Math.ceil((end-Date.now())/1000));if($('p1Clock'))$('p1Clock').textContent=mmss(left);if(left===10)tone(700,.1);if(!left)stop()},250);draw()}},
activity:{group:'Calculadoras',icon:'🚶',name:'Calorias de outras atividades',hint:'Caminhar, correr, bicicleta…',run(box){const b=body();box.innerHTML=`<div class="tool-form"><label class="tool-field">Atividade<select id="acType">${P.activities.map(([n,m],i)=>`<option value="${m}">${esc(n)}</option>`).join('')}</select></label><label class="tool-field">Minutos<input id="acMin" type="number" min="1" max="600" value="30" inputmode="numeric"></label><label class="tool-field">O teu peso (kg)<input id="acKg" type="number" min="25" max="300" step="0.1" value="${esc(b.weight||'')}" inputmode="decimal"></label></div><div id="acOut" class="tool-out"></div><p class="source-note">Estimativa geral; depende muito da intensidade.</p>`;const calc=()=>{const v=P.activityKcal(Number($('acType').value),Number($('acMin').value),Number($('acKg').value));$('acOut').innerHTML=v?`<p class="tool-big">${v} kcal</p>`:'<p class="source-note">Preenche os minutos e o peso.</p>'};box.addEventListener('input',calc);box.addEventListener('change',calc);calc()}},
quizmuscle:{group:'Jogos',icon:'🧠',name:'Que músculo trabalha?',hint:'Aprende a jogar',run(box){const pool=[...byId.values()].filter(e=>e.images?.length&&e.primaryMuscles?.length&&['body only','dumbbell'].includes(e.equipment)&&e.category==='strength'),muscles=[...new Set(pool.flatMap(e=>e.primaryMuscles))];let score=0,round=0,best=local('cal_ui_quiz1',0);const next=()=>{round++;const e=pool[Math.floor(Math.random()*pool.length)],right=e.primaryMuscles[0],opts=P.shuffle([right,...P.shuffle(muscles.filter(m=>!e.primaryMuscles.includes(m))).slice(0,3)]);box.innerHTML=`<p class="tool-sub">Pergunta ${round} · ${score} certas${best?' · recorde '+best:''}</p>${window.ExecutionMedia?ExecutionMedia.thumb(e,esc,'tool-thumb tool-thumb-big'):''}<h3 class="quiz-q">${esc(e.title)}</h3><p>Qual é o músculo principal?</p><div class="quiz-opts">${opts.map(m=>`<button type="button" data-q="${esc(m)}">${esc(ExerciseCore.muscles[m]||m)}</button>`).join('')}</div><div id="quizOut"></div>`;box.querySelector('.quiz-opts').onclick=ev=>{const b=ev.target.closest('[data-q]');if(!b||box.querySelector('.quiz-opts').dataset.done)return;box.querySelector('.quiz-opts').dataset.done='1';const ok=b.dataset.q===right;if(ok){score++;tone(880,.15);vib(30)}else{tone(300,.3);vib([60,60,60])}box.querySelectorAll('[data-q]').forEach(x=>{if(x.dataset.q===right)x.classList.add('is-right');else if(x===b)x.classList.add('is-wrong')});if(score>best){best=score;setLocal('cal_ui_quiz1',best)}$('quizOut').innerHTML=`<p class="tool-out">${ok?'✓ Certo!':'✗ É '+esc(ExerciseCore.muscles[right]||right)+'.'}</p><div class="tool-row"><button class="primary" id="quizNext">Seguinte →</button></div>`;$('quizNext').onclick=next}};next()}},
quizfood:{group:'Jogos',icon:'🍩',name:'Qual tem mais calorias?',hint:'Duas comidas, uma escolha',run(box){const F=window.FoodCore;if(!F){box.textContent='Indisponível.';return}const pool=F.foods.filter(f=>f.kcal>20&&f.unit==='g');let score=0,round=0,best=local('cal_ui_quiz2',0);const next=()=>{round++;let [a,b]=P.shuffle(pool).slice(0,2);while(Math.abs(F.amount(a,a.por).kcal-F.amount(b,b.por).kcal)<30)b=pool[Math.floor(Math.random()*pool.length)];const ka=F.amount(a,a.por).kcal,kb=F.amount(b,b.por).kcal;box.innerHTML=`<p class="tool-sub">Pergunta ${round} · ${score} certas${best?' · recorde '+best:''}</p><p>Qual destas porções tem mais calorias?</p><div class="quiz-food">${[[a,ka],[b,kb]].map(([f,k],i)=>`<button type="button" data-f="${i}"><strong>${esc(f.name)}</strong><small>${f.por} g</small><b class="quiz-k" hidden>${k} kcal</b></button>`).join('')}</div><div id="quizOut"></div>`;box.querySelector('.quiz-food').onclick=ev=>{const btn=ev.target.closest('[data-f]'),wrap=box.querySelector('.quiz-food');if(!btn||wrap.dataset.done)return;wrap.dataset.done='1';const pick=Number(btn.dataset.f),ok=(pick===0?ka>=kb:kb>=ka);if(ok){score++;tone(880,.15);vib(30)}else{tone(300,.3);vib([60,60,60])}box.querySelectorAll('.quiz-k').forEach(k=>k.hidden=false);btn.classList.add(ok?'is-right':'is-wrong');if(score>best){best=score;setLocal('cal_ui_quiz2',best)}$('quizOut').innerHTML=`<p class="tool-out">${ok?'✓ Certo!':'✗ Errado.'} ${esc(a.name)}: ${ka} kcal · ${esc(b.name)}: ${kb} kcal</p><div class="tool-row"><button class="primary" id="quizNext">Seguinte →</button></div>`;$('quizNext').onclick=next}};next()}},
checklist:{group:'Bem-estar',icon:'✅',name:'Antes de treinar',hint:'Lista para não esquecer nada',run(box){const base=['Garrafa de água','Toalha','Roupa e calçado confortáveis','Espaço livre à volta','Telemóvel com bateria','Material do treino','5 minutos para aquecer'];const draw=()=>{const s={date:'',done:[],own:[],...local('cal_ui_check',{})};if(s.date!==today()){s.date=today();s.done=[]}setLocal('cal_ui_check',s);const all=[...base,...s.own];box.innerHTML=`<ul class="tool-checklist">${all.map((t,i)=>`<li><label><input type="checkbox" data-ck="${esc(t)}" ${s.done.includes(t)?'checked':''}> ${esc(t)}</label>${i>=base.length?`<button class="text-button" data-rm="${esc(t)}" aria-label="Apagar">×</button>`:''}</li>`).join('')}</ul><p class="tool-out">${s.done.length>=all.length?'🎉 Tudo pronto. Bom treino!':(all.length-s.done.length)+' por marcar'}</p><form id="ckForm" class="tool-add"><input id="ckNew" maxlength="40" placeholder="Acrescentar à lista"><button class="secondary">Adicionar</button></form>`;
 box.querySelectorAll('[data-ck]').forEach(c=>c.onchange=()=>{const v=c.dataset.ck;s.done=c.checked?[...new Set([...s.done,v])]:s.done.filter(x=>x!==v);setLocal('cal_ui_check',s);draw()});box.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{s.own=s.own.filter(x=>x!==b.dataset.rm);setLocal('cal_ui_check',s);draw()});$('ckForm').onsubmit=e=>{e.preventDefault();const v=$('ckNew').value.trim();if(v&&!all.includes(v)){s.own=[...s.own,v].slice(0,20);setLocal('cal_ui_check',s);draw()}}};draw()}}
};

// The tool hub at the top of Ferramentas, grouped and searchable.
const groups=[...new Set(Object.values(TOOLS).map(t=>t.group))];
const hub=document.createElement('section');hub.className='tool-hub';hub.setAttribute('aria-label','Mais ferramentas');
hub.innerHTML=`<label class="tool-search"><span class="sr-only">Procurar uma ferramenta</span><input id="toolSearch" type="search" placeholder="🔎 Procurar: cronómetro, água, IMC…" autocomplete="off"></label><div id="toolRecent" class="tool-recent"></div>${groups.map(g=>`<div class="tool-group" data-group="${esc(g)}"><h3>${esc(g)}</h3><div class="tool-grid">${Object.entries(TOOLS).filter(([,t])=>t.group===g).map(([id,t])=>`<button type="button" class="tool-tile" data-tool="${id}" data-words="${esc((t.name+' '+(t.hint||'')+' '+g).toLowerCase())}"><span aria-hidden="true">${t.icon}</span><strong>${esc(t.name)}</strong>${t.hint?`<small>${esc(t.hint)}</small>`:''}</button>`).join('')}</div></div>`).join('')}`;
const heading=$('toolsPanel')?.querySelector('.studio-page-heading');if(heading)heading.after(hub);else $('toolsPanel')?.prepend(hub);
hub.addEventListener('click',e=>{const b=e.target.closest('[data-tool]');if(b)open(b.dataset.tool)});
$('toolSearch').addEventListener('input',()=>{const q=$('toolSearch').value.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');hub.querySelectorAll('.tool-tile').forEach(t=>{t.hidden=!!q&&!t.dataset.words.normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)});hub.querySelectorAll('.tool-group').forEach(g=>{g.hidden=![...g.querySelectorAll('.tool-tile')].some(t=>!t.hidden)})});
renderRecent();
window.PracticalTools={open,list:()=>Object.entries(TOOLS).map(([id,t])=>({id,...t}))};
return {open};
};
